#!/usr/bin/env node
/**
 * Builds the shipping rasters of `public/brand/` from the generated masters in `site/source/gen/` (never served).
 * CLIENT ZONE. Every picture is an illustration generated by AI (openai/gpt-image-2 through the studio MCP); the exact prompt of each
 * generation sits in `site/source/gen/<name>/*.json` beside its master (see site/IMAGES_A_GENERER.md).
 *   node site/tools/images.mjs
 *
 * Masters (site/source/gen/<name>/*.png, the newest PNG of each folder is used):
 *   hero            1536x1024  butter chicken, rice and naan on a flat off-white ground (cut out here, alpha by flood fill)
 *   facade counter tandoor  2048x1152 scenes
 *   sheet-1 .. 8    2304x1536  contact sheets, 3 columns x 2 rows of products on a flat cream ground (SHEETS below gives the slugs)
 * Also built here: logo/kurry-up.svg (PLACEHOLDER mark, "logo a fournir"), icon-192.png (placeholder), og-default.jpg.
 */
import fs from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"
import sharp from "sharp"

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..")
const B = path.join(ROOT, "public/brand")
const G = path.join(ROOT, "site/source/gen")
const out = (f) => {
  fs.mkdirSync(path.dirname(path.join(B, f)), { recursive: true })
  return path.join(B, f)
}
const master = (name) => {
  const dir = path.join(G, name)
  const files = fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith(".png")).sort() : []
  return files.length ? path.join(dir, files[files.length - 1]) : null
}
const made = []
const note = (f) => made.push(f)

/* ── Scenes: 16:9, WebP 1920x1080 and -sm 960x540 ─────────────────────────────────────────────────────────────── */
for (const name of ["facade", "counter", "tandoor"]) {
  const src = master(name)
  if (!src) { console.warn(`missing master: ${name}`); continue }
  await sharp(src).resize(1920, 1080).webp({ quality: 80, effort: 6 }).toFile(out(`scenes/${name}.webp`))
  await sharp(src).resize(960, 540).webp({ quality: 76, effort: 6 }).toFile(out(`scenes/${name}-sm.webp`))
  note(`scenes/${name}.webp`)
}

/* ── Hero: the meal cut out of its flat off-white ground ─────────────────────────────────────────────────────────
 * Colour key by flood fill from the four edges (pixels within HERO_T of the ground, L1 distance), so the white rice inside the plate
 * is never opened. The mask is eroded about one pixel against halos and softened by 0.7 px. The canvas is trimmed to the meal plus a margin. */
{
  const src = master("hero")
  if (src) {
    const HERO_T = 34
    const { data, info } = await sharp(src).removeAlpha().raw().toBuffer({ resolveWithObject: true })
    const W = info.width, H = info.height
    const at = (x, y) => (y * W + x) * 3
    const corners = [[6, 6], [W - 7, 6], [6, H - 7], [W - 7, H - 7]].map(([x, y]) => [data[at(x, y)], data[at(x, y) + 1], data[at(x, y) + 2]])
    const bg = [0, 1, 2].map((c) => corners.map((p) => p[c]).sort((a, b) => a - b)[1])
    const isBg = (i) => Math.abs(data[i] - bg[0]) + Math.abs(data[i + 1] - bg[1]) + Math.abs(data[i + 2] - bg[2]) < HERO_T
    const outside = new Uint8Array(W * H)
    const stack = []
    const push = (x, y) => {
      const k = y * W + x
      if (!outside[k] && isBg(k * 3)) { outside[k] = 1; stack.push(k) }
    }
    for (let x = 0; x < W; x++) { push(x, 0); push(x, H - 1) }
    for (let y = 0; y < H; y++) { push(0, y); push(W - 1, y) }
    while (stack.length) {
      const k = stack.pop(), x = k % W, y = (k - x) / W
      if (x > 0) push(x - 1, y)
      if (x < W - 1) push(x + 1, y)
      if (y > 0) push(x, y - 1)
      if (y < H - 1) push(x, y + 1)
    }
    const alpha = Buffer.alloc(W * H)
    for (let k = 0; k < W * H; k++) alpha[k] = outside[k] ? 0 : 255
    const softRaw = await sharp(alpha, { raw: { width: W, height: H, channels: 1 } }).blur(1.6).threshold(170).blur(0.7).raw().toBuffer({ resolveWithObject: true })
    const sc = softRaw.info.channels // stride of the grey mask (1, or 3 if sharp widened it)
    const soft = Buffer.alloc(W * H)
    for (let k = 0; k < W * H; k++) soft[k] = softRaw.data[k * sc]
    const rgba = Buffer.alloc(W * H * 4)
    for (let k = 0; k < W * H; k++) {
      rgba[k * 4] = data[k * 3]; rgba[k * 4 + 1] = data[k * 3 + 1]; rgba[k * 4 + 2] = data[k * 3 + 2]; rgba[k * 4 + 3] = soft[k]
    }
    let x0 = W, y0 = H, x1 = 0, y1 = 0
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (soft[y * W + x] > 12) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y }
    const pad = 28
    x0 = Math.max(0, x0 - pad); y0 = Math.max(0, y0 - pad); x1 = Math.min(W - 1, x1 + pad); y1 = Math.min(H - 1, y1 + pad)
    const crop = await sharp(rgba, { raw: { width: W, height: H, channels: 4 } })
      .extract({ left: x0, top: y0, width: x1 - x0 + 1, height: y1 - y0 + 1 }).png().toBuffer()
    const meta = await sharp(crop).metadata()
    await sharp(crop).webp({ quality: 88, alphaQuality: 92, effort: 6 }).toFile(out("hero/street-food.webp"))
    await sharp(crop).resize(Math.round(meta.width / 2)).webp({ quality: 84, alphaQuality: 90, effort: 6 }).toFile(out("hero/street-food-sm.webp"))
    note(`hero/street-food.webp (${meta.width}x${meta.height}, transparent)`)
  } else console.warn("missing master: hero")
}

/* ── Product sheets: 3 columns x 2 rows, slugs in reading order ───────────────────────────────────────────────── */
const SHEETS = {
  "sheet-1": ["butter-chicken", "poulet-tikka-massala", "poulet-korma", "poulet-karahi", "agneau-karahi", "palak-paneer"],
  "sheet-2": ["menu-kurry-up", "bowl-kurry-up", "biryani-poulet", "samossa", "naan-fromage", "lassi"],
  "sheet-3": ["poulet-tikka", "cookie-chocolat-au-lait", "pakora", "samossa-chaat", "raita", "soupe-de-lentilles"],
  "sheet-4": ["salade-raja", "salade-rani", "agneau-madras", "agneau-shahi-korma", "daal-tarka", "aubergine-massala"],
  "sheet-5": ["chana-massala", "biryani-legumes", "biryani-agneau", "biryani-crevettes", "naan-nature", "naan-ail"],
  "sheet-6": ["naan-ail-fromage", "chapati", "naan-chocolat-noisette", "cookie-caramel-cacahuete", "fromage-blanc-mangue-muesli", "sandwich-a-composer"],
  "sheet-7": ["mousse-au-chocolat", "mangue-menthe", "the-indien", "eau-de-coco", "kombucha", "jus-indien-25-cl"],
  "sheet-8": ["eau-33-cl", "soda-33-cl", "the-glace-33-cl", "the-glace-50-cl", "biere-indienne-33-cl", "extra-chutneys"],
}
const GROUND = [244, 234, 218] // common cream ground, every sheet is pulled to it (their own grounds differ by up to 4 levels)
const OUT = 800 // delivered square, the 768 px cells are enlarged by 4 %
const MARGIN = 1.16 // square side = longest side of the subject x MARGIN
const MIN_SIDE = 660, MAX_SIDE = 1000

/** The empty gap of a projection nearest to `target`: centre of the longest zero run in [lo, hi], else the minimum. */
function cutAt(proj, target, lo, hi) {
  let best = null, runStart = -1
  for (let i = lo; i <= hi + 1; i++) {
    const empty = i <= hi && proj[i] < 4
    if (empty && runStart < 0) runStart = i
    if (!empty && runStart >= 0) {
      const run = { len: i - runStart, mid: Math.round((runStart + i - 1) / 2) }
      if (!best || run.len > best.len || (run.len === best.len && Math.abs(run.mid - target) < Math.abs(best.mid - target))) best = run
      runStart = -1
    }
  }
  if (best) return best.mid
  let m = lo
  for (let i = lo; i <= hi; i++) if (proj[i] < proj[m]) m = i
  return m
}

for (const [name, slugs] of Object.entries(SHEETS)) {
  const src = master(name)
  if (!src) { console.warn(`missing master: ${name}`); continue }
  const raw = await sharp(src).removeAlpha().raw().toBuffer({ resolveWithObject: true })
  const W = raw.info.width, H = raw.info.height
  const px = raw.data
  const at = (x, y) => (y * W + x) * 3
  const patches = [[10, 10], [W - 50, 10], [10, H - 50], [W - 50, H - 50]]
  const med = [0, 1, 2].map((c) => {
    const v = []
    for (const [px0, py0] of patches) for (let y = py0; y < py0 + 40; y += 4) for (let x = px0; x < px0 + 40; x += 4) v.push(px[at(x, y) + c])
    return v.sort((a, b) => a - b)[v.length >> 1]
  })
  // subject mask: L1 distance to the sheet's own ground
  const mask = new Uint8Array(W * H)
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const i = at(x, y)
    mask[y * W + x] = Math.abs(px[i] - med[0]) + Math.abs(px[i + 1] - med[1]) + Math.abs(px[i + 2] - med[2]) > 60 ? 1 : 0
  }
  const rowProj = new Int32Array(H)
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) rowProj[y] += mask[y * W + x]
  const rowCut = cutAt(rowProj, H / 2, Math.round(H * 0.4), Math.round(H * 0.6))
  const bands = [[0, rowCut], [rowCut, H]]
  // sheet pulled to the common ground (gains stay within 4 %)
  const norm = await sharp(src).removeAlpha().linear(GROUND.map((g, c) => g / med[c]), [0, 0, 0]).raw().toBuffer()
  const PADDING = 520
  const groundBg = { r: GROUND[0], g: GROUND[1], b: GROUND[2] }
  for (let n = 0; n < slugs.length; n++) {
    const slug = slugs[n], col = n % 3, row = Math.floor(n / 3)
    const [by0, by1] = bands[row]
    const colProj = new Int32Array(W)
    for (let y = by0; y < by1; y++) for (let x = 0; x < W; x++) colProj[x] += mask[y * W + x]
    const c1 = cutAt(colProj, W / 3, Math.round(W * 0.24), Math.round(W * 0.42))
    const c2 = cutAt(colProj, (2 * W) / 3, Math.round(W * 0.58), Math.round(W * 0.76))
    const cols = [[0, c1], [c1, c2], [c2, W]]
    const [bx0, bx1] = cols[col]
    let x0 = bx1, x1 = bx0, y0 = by1, y1 = by0
    for (let y = by0; y < by1; y++) for (let x = bx0; x < bx1; x++) if (mask[y * W + x]) {
      if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y
    }
    const w = x1 - x0 + 1, h = y1 - y0 + 1
    const side = Math.round(Math.min(MAX_SIDE, Math.max(MIN_SIDE, Math.max(w, h) * MARGIN)))
    const left = Math.round((x0 + x1) / 2 - side / 2) + PADDING
    const top = Math.round((y0 + y1) / 2 - side / 2) + PADDING
    // only this cell's own area is kept: everything else (the neighbours' edges) is painted with the ground
    const cell = await sharp(norm, { raw: { width: W, height: H, channels: 3 } })
      .extract({ left: bx0, top: by0, width: bx1 - bx0, height: by1 - by0 }).png().toBuffer()
    const canvas = await sharp({ create: { width: W + 2 * PADDING, height: H + 2 * PADDING, channels: 3, background: groundBg } })
      .composite([{ input: cell, left: bx0 + PADDING, top: by0 + PADDING }]).raw().toBuffer({ resolveWithObject: true })
    const square = await sharp(canvas.data, { raw: canvas.info })
      .extract({ left, top, width: side, height: side }).resize(OUT, OUT, { kernel: "lanczos3" }).png().toBuffer()
    await sharp(square).webp({ quality: 82, effort: 6 }).toFile(out(`products/${slug}.webp`))
    await sharp(square).resize(400, 400, { kernel: "lanczos3" }).webp({ quality: 80, effort: 6 }).toFile(out(`products/${slug}-sm.webp`))
    note(`products/${slug}.webp`)
  }
}

/* ── Logo: PLACEHOLDER ("logo a fournir"), geometric stroke letters, no font needed. Replace by the brand's own file. ── */
const LETTERS = {
  K: "M9 4V96M56 4L9 56M24 42L58 96",
  U: "M9 4V66A21 30 0 0 0 51 66V4",
  R: "M9 96V4H34A21 21 0 0 1 34 46H9M30 46L55 96",
  Y: "M4 4L30 50L56 4M30 50V96",
  P: "M9 96V4H34A21 21 0 0 1 34 46H9",
}
const WORD = [["K", 0], ["U", 82], ["R", 164], ["R", 246], ["Y", 328], ["U", 450], ["P", 532]]
const logoPaths = WORD.map(([l, x]) => `<path transform="translate(${x} 0)" d="${LETTERS[l]}"/>`).join("")
const logoSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-12 -8 628 116" role="img" aria-labelledby="t">
  <title id="t">Kurry Up (logo provisoire, à fournir par la marque)</title>
  <!-- PLACEHOLDER mark: plain letters, not the brand's logo. Replace by the logo supplied by Kurry Up. -->
  <g fill="none" stroke="#010000" stroke-width="17" stroke-linejoin="miter" stroke-linecap="butt">${logoPaths}</g>
</svg>
`
fs.writeFileSync(out("logo/kurry-up.svg"), logoSvg)
note("logo/kurry-up.svg (placeholder)")

/* Icon 192: orange disc-free square #ea5800 with a plain K in ink #1F1712 (placeholder). */
const iconSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="192" height="192" viewBox="0 0 192 192"><rect width="192" height="192" fill="#ea5800"/><g transform="translate(46 36) scale(1.2)" fill="none" stroke="#1F1712" stroke-width="17" stroke-linejoin="miter" stroke-linecap="butt"><path d="${LETTERS.K}"/></g></svg>`
await sharp(Buffer.from(iconSvg)).png().toFile(out("icon-192.png"))
note("icon-192.png (placeholder)")

/* ── Share card 1200x630 from the facade scene, no text ───────────────────────────────────────────────────── */
{
  const src = master("facade")
  if (src) {
    await sharp(src).resize(1200, 630, { fit: "cover", position: "centre" }).jpeg({ quality: 86, mozjpeg: true, chromaSubsampling: "4:4:4" }).toFile(out("og-default.jpg"))
    note("og-default.jpg")
  }
}

/* ── Contract check: the files the seed expects (site/seed/data.mjs MEDIA) ────────────────────────────────────── */
const CONTRACT = [
  "logo/kurry-up.svg", "icon-192.png", "og-default.jpg", "hero/street-food.webp",
  "scenes/facade.webp", "scenes/counter.webp", "scenes/tandoor.webp",
  ...["samossa", "butter-chicken", "poulet-tikka-massala", "agneau-karahi", "biryani-poulet", "naan-fromage", "lassi", "bowl-kurry-up", "menu-kurry-up"].map((s) => `products/${s}.webp`),
]
const allSlugs = Object.values(SHEETS).flat().filter((s) => !s.startsWith("extra-"))
const missing = [...CONTRACT, ...allSlugs.flatMap((s) => [`products/${s}.webp`, `products/${s}-sm.webp`])].filter((f) => !fs.existsSync(path.join(B, f)))
console.log(`built ${made.length} entries into public/brand`)
console.log(missing.length ? `MISSING (${missing.length}):\n  ${missing.join("\n  ")}` : "contract complete: every expected file exists")
